  Tensor tAgA = local_partition(gA, tA, threadIdx.x);   // (BLK_M/32, BLK_K/8, k)
  Tensor tAsA = local_partition(sA, tA, threadIdx.x);   // (BLK_M/32, BLK_K/8)
  Tensor tBgB = local_partition(gB, tB, threadIdx.x);   // (BLK_N/32, BLK_K/8, k)
  Tensor tBsB = local_partition(sB, tB, threadIdx.x);   // (BLK_N/32, BLK_K/8)

  Tensor tCsA = local_partition(sA, tC, threadIdx.x, Step<_1, X>{});  // (BLK_M/16, BLK_K)
  Tensor tCsB = local_partition(sB, tC, threadIdx.x, Step< X,_1>{});  // (BLK_N/16, BLK_K)
  Tensor tCgC = local_partition(gC, tC, threadIdx.x, Step<_1,_1>{});  // (BLK_M/16, BLK_N/16)

  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);

  int K_TILE_MAX = size<2>(tAgA);
  for (int k_tile = 0; k_tile < K_TILE_MAX; ++k_tile) {
    copy(tAgA(_,_,k_tile), tAsA);
    copy(tBgB(_,_,k_tile), tBsB);

    __syncthreads();

    gemm(tCsA, tCsB, tCrC);

    __syncthreads();
  }

  // Epilogue: write result
  axpby(T(1), tCrC, T(0), tCgC);
}

torch::Tensor cute_gemm_forward(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();

  int M = (int)A_c.size(0);
  int K = (int)A_c.size(1);
  int N = (int)B_c.size(1);
  TORCH_CHECK((int)B_c.size(0) == K, "Inner dimensions of A and B must match");

  constexpr int BLK_M = 128;
  constexpr int BLK_N = 128;
  constexpr int BLK_K = 32;

  auto C = torch::empty({M, N}, A.options());

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  if (M % BLK_M == 0 && N % BLK_N == 0 && K % BLK_K == 0) {
    dim3 dimBlock(256);
    dim3 dimGrid(M / BLK_M, N / BLK_N);

    gemm_device<float, BLK_M, BLK_N, BLK_K><<<dimGrid, dimBlock, 0, stream>>>(
        M, N, K,
        A_c.data_ptr<float>(),
        B_c.data_ptr<float>(),
        C.data_ptr<float>()
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "CUTE gemm launch failed: ", cudaGetErrorString(err));
  } else {
    // Fallback for shapes that don't fit the tiling assumptions
    C = at::matmul(A_c, B_c);
  }

  return C;
}
